CREATE OR REPLACE FUNCTION public.base_ready_bonus_refresh_status_v1(p_bonus_id bigint)
 RETURNS base_ready_bonuses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_bonus public.base_ready_bonuses%rowtype;
  v_status text;
begin
  select *
  into v_bonus
  from public.base_ready_bonuses
  where id = p_bonus_id
  for update;

  if not found then
    raise exception 'BASE_READY_BONUS_NOT_FOUND';
  end if;

  if v_bonus.status in ('VOIDED','REVIEW_REQUIRED','INELIGIBLE') then
    return v_bonus;
  end if;

  if v_bonus.retained_amount >= v_bonus.amount-0.005 then
    v_status := 'RETAINED';
  elsif v_bonus.reserved_amount >= v_bonus.amount-v_bonus.retained_amount-0.005
        and v_bonus.remaining_amount <= 0.005 then
    v_status := 'RESERVED';
  elsif v_bonus.reserved_amount > 0.005 then
    v_status := 'PARTIAL_RESERVED';
  elsif v_bonus.retained_amount > 0.005 then
    v_status := 'PARTIAL_RETAINED';
  else
    v_status := 'EARNED';
  end if;

  update public.base_ready_bonuses
  set status=v_status,
      activated_at=coalesce(activated_at,ready_at),
      activation_source=coalesce(nullif(activation_source,''),'GATI'),
      updated_at=now()
  where id=p_bonus_id
  returning * into v_bonus;

  return v_bonus;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_bujar_only_base_bonus_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_bujar_pin text;
begin
  select pin into v_bujar_pin from public.users where id='19d3ab97-2067-493a-aeb1-8a23572dc5f8' and is_active is true limit 1;
  if coalesce(new.worker_pin,'') <> coalesce(v_bujar_pin,'__NO_BUJAR__') then
    new.eligible := false;
    new.amount := 0;
    new.remaining_amount := 0;
    new.reserved_amount := 0;
    new.retained_amount := 0;
    new.status := 'INELIGIBLE';
    new.reason := 'WORKER_NOT_EXCLUSIVE_BUJAR';
  else
    new.worker_name := 'bujar oruqi';
    new.rate_m2 := 0.10;
    if coalesce(new.eligible,false) then
      new.amount := round(coalesce(new.m2,0)*0.10,2);
      new.remaining_amount := greatest(0,new.amount-coalesce(new.reserved_amount,0)-coalesce(new.retained_amount,0));
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_cash_handoff_with_ready_bonus_v1(actor_pin text, actor_name text DEFAULT NULL::text, actor_role text DEFAULT NULL::text, payment_ids bigint[] DEFAULT NULL::bigint[], amount_declared numeric DEFAULT NULL::numeric, handoff_note text DEFAULT NULL::text, idempotency_key text DEFAULT NULL::text, meal_payment_ids bigint[] DEFAULT NULL::bigint[], ready_bonus_payment_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_base jsonb;
  v_handoff public.cash_handoffs%rowtype;
  v_handoff_id bigint;
  v_bonus_ids bigint[] := array[]::bigint[];
  v_verify_ids bigint[] := array[]::bigint[];
  v_requested_bonus_count integer := 0;
  v_valid_bonus_count integer := 0;
  v_existing_bonus_total numeric := 0;
  v_bonus_total numeric := 0;
  v_available numeric := 0;
  v_alloc numeric := 0;
  v_left numeric := 0;
  v_cut numeric := 0;
  v_remaining_after numeric := 0;
  v_bonus public.base_ready_bonuses%rowtype;
  v_item record;
  v_item_sum numeric := 0;
  v_item_count integer := 0;
  v_payment_statuses jsonb := '[]'::jsonb;
  v_allocation_ids jsonb := '[]'::jsonb;
begin
  v_base := public.submit_cash_handoff_atomic(
    actor_pin,
    actor_name,
    actor_role,
    payment_ids,
    null,
    handoff_note,
    idempotency_key,
    meal_payment_ids
  );

  v_handoff_id := nullif(v_base->'handoff'->>'id','')::bigint;
  if v_handoff_id is null then
    raise exception 'BONUS_HANDOFF_RESPONSE_MISSING_ID';
  end if;

  select * into v_handoff
  from public.cash_handoffs
  where id = v_handoff_id
  for update;
  if not found then
    raise exception 'BONUS_HANDOFF_NOT_FOUND';
  end if;

  select round(coalesce(sum(a.amount),0),2)
  into v_existing_bonus_total
  from public.base_ready_bonus_allocations a
  where a.handoff_id = v_handoff_id
    and a.status in ('RESERVED','RETAINED');

  if ready_bonus_payment_ids is not null and array_length(ready_bonus_payment_ids,1) is not null then
    select coalesce(array_agg(distinct x order by x),array[]::bigint[])
    into v_bonus_ids
    from unnest(ready_bonus_payment_ids) x
    where x is not null and x > 0;
  end if;
  v_requested_bonus_count := coalesce(array_length(v_bonus_ids,1),0);

  if v_existing_bonus_total <= 0.005 and v_requested_bonus_count > 0 then
    select count(*)::integer into v_valid_bonus_count
    from public.base_ready_bonuses b
    where b.arka_payment_id = any(v_bonus_ids)
      and b.worker_pin = btrim(coalesce(actor_pin,''))
      and b.eligible is true
      and b.remaining_amount > 0.005
      and b.status not in ('VOIDED','REVIEW_REQUIRED','INELIGIBLE');

    if v_valid_bonus_count <> v_requested_bonus_count then
      raise exception 'READY_BONUS_PAYMENT_NOT_AVAILABLE requested=% valid=%',v_requested_bonus_count,v_valid_bonus_count;
    end if;

    v_available := greatest(0, round(v_handoff.amount - 0.01,2));

    for v_bonus in
      select b.*
      from public.base_ready_bonuses b
      where b.arka_payment_id = any(v_bonus_ids)
        and b.worker_pin = btrim(coalesce(actor_pin,''))
        and b.eligible is true
        and b.remaining_amount > 0.005
        and b.status not in ('VOIDED','REVIEW_REQUIRED','INELIGIBLE')
      order by b.ready_at asc,b.id asc
      for update
    loop
      exit when v_available <= 0.005;
      v_alloc := least(v_bonus.remaining_amount,v_available);
      if v_alloc <= 0.005 then
        continue;
      end if;

      insert into public.base_ready_bonus_allocations (bonus_id,handoff_id,amount,status,created_at,updated_at)
      values (v_bonus.id,v_handoff_id,round(v_alloc,2),'RESERVED',now(),now())
      on conflict (bonus_id,handoff_id) do nothing;

      if found then
        update public.base_ready_bonuses
        set remaining_amount = round(greatest(0,remaining_amount-v_alloc),2),
            reserved_amount = round(reserved_amount+v_alloc,2),
            updated_at = now()
        where id = v_bonus.id
        returning remaining_amount into v_remaining_after;

        perform public.base_ready_bonus_refresh_status_v1(v_bonus.id);

        update public.arka_pending_payments
        set handoff_note = case
              when v_remaining_after <= 0.005 then concat('SETTLED_IN_HANDOFF:',v_handoff_id,'|READY_BONUS:',v_bonus.id)
              else concat('READY_BONUS_OPEN:',v_bonus.id,'|PARTIAL_IN_HANDOFF:',v_handoff_id,':',to_char(v_alloc,'FM999999990.00'))
            end,
            handed_at = now(),
            handed_by_pin = actor_pin,
            handed_by_name = actor_name,
            handed_by_role = actor_role,
            updated_at = now()
        where id = v_bonus.arka_payment_id;

        v_bonus_total := round(v_bonus_total + v_alloc,2);
        v_available := round(v_available - v_alloc,2);
      end if;
    end loop;

    if v_bonus_total > 0.005 then
      v_left := v_bonus_total;
      for v_item in
        select id,amount
        from public.cash_handoff_items
        where handoff_id = v_handoff_id
        order by amount desc,id asc
        for update
      loop
        exit when v_left <= 0.005;
        v_cut := least(v_item.amount,v_left);
        if v_cut > 0 then
          update public.cash_handoff_items
          set amount = round(greatest(0,amount-v_cut),2)
          where id = v_item.id;
          v_left := round(v_left-v_cut,2);
        end if;
      end loop;

      if v_left > 0.005 then
        raise exception 'READY_BONUS_HANDOFF_ITEM_REDUCTION_FAILED remaining=%',v_left;
      end if;

      update public.cash_handoffs
      set amount = round(amount-v_bonus_total,2),
          note = concat_ws(' | ',nullif(note,''),concat('BONUS 48H MBAJTUR ',to_char(v_bonus_total,'FM999999990.00'),'€'))
      where id = v_handoff_id
      returning * into v_handoff;
    end if;
  else
    v_bonus_total := v_existing_bonus_total;
  end if;

  if amount_declared is not null and amount_declared > 0 and abs(round(amount_declared,2)-round(v_handoff.amount,2)) > 0.05 then
    raise exception 'HANDOFF_DECLARED_AMOUNT_MISMATCH_AFTER_READY_BONUS declared=% computed=%',amount_declared,v_handoff.amount;
  end if;

  select round(coalesce(sum(i.amount),0),2),count(*)::integer
  into v_item_sum,v_item_count
  from public.cash_handoff_items i
  where i.handoff_id = v_handoff_id;

  if abs(v_item_sum-v_handoff.amount) > 0.05 then
    raise exception 'READY_BONUS_HANDOFF_SUM_MISMATCH handoff=% items=%',v_handoff.amount,v_item_sum;
  end if;

  select coalesce(array_agg(distinct x order by x),array[]::bigint[])
  into v_verify_ids
  from unnest(
    coalesce(payment_ids,array[]::bigint[])
    || coalesce(meal_payment_ids,array[]::bigint[])
    || coalesce(v_bonus_ids,array[]::bigint[])
  ) x
  where x is not null and x > 0;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p.id,
    'type',p.type,
    'status',p.status,
    'handoff_note',p.handoff_note
  ) order by p.id),'[]'::jsonb)
  into v_payment_statuses
  from public.arka_pending_payments p
  where p.id = any(v_verify_ids);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',a.id,
    'bonus_id',a.bonus_id,
    'amount',a.amount,
    'status',a.status
  ) order by a.id),'[]'::jsonb)
  into v_allocation_ids
  from public.base_ready_bonus_allocations a
  where a.handoff_id = v_handoff_id
    and a.status in ('RESERVED','RETAINED');

  return v_base || jsonb_build_object(
    'ok',true,
    'handoff',to_jsonb(v_handoff),
    'total',round(v_handoff.amount,2),
    'readyBonusTotal',round(v_bonus_total,2),
    'readyBonusAllocations',v_allocation_ids,
    'verification',jsonb_build_object(
      'paymentCount',coalesce(array_length(v_verify_ids,1),0),
      'paymentStatuses',v_payment_statuses,
      'itemCount',v_item_count,
      'itemSum',v_item_sum,
      'handoffAmount',round(v_handoff.amount,2)
    )
  );
end;
$function$
